Lemma MBraw_rheap_pres : forall LB SP m m' b es out insz outpos outend,
  MBraw m b es out insz outpos outend -> MBufOwn LB es -> rheap_pres LB SP m m' -> SP <= b ->
  MBraw m' b es out insz outpos outend.
Proof.
  intros LB SP m m' b es out insz outpos outend (ls & H0 & H1 & DL & LC & EL & AOK) OWN HP LE.
  pose proof AOK as (AD & DJ & HB & B64 & AL).
  assert (ER : forall x s, In (x, s) es -> rclient_range LB SP x (24 + s)).
  { intros x s IN. destruct (OWN x s IN) as [p INb]. destruct (AD x s IN) as (_ & _ & S0 & _).
    pose proof (mb_block_size_range s S0) as [R _]. right; right. exists (p, x, mb_block_size s). split; [exact INb| cbn; lia]. }
  exists ls. split. { eapply rheap_pres_rw_cells; [exact HP| exact H0| left; cbn; lia]. }
  split. { eapply rheap_pres_rw_cells; [exact HP| exact H1| left; cbn; lia]. }
  split; [exact DL|]. split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|].
    eapply rheap_pres_rw_cells; [exact HP| exact C|]. cbn [cells_size csize Nat.add LNodeCells].
    destruct (mb_lnode_cases _ _ _ _ _ DL AOK La) as [->|(s & IN & _ & _ & S0 & _)]; [left; lia|].
    eapply rclient_range_sub; [exact (ER a s IN)| lia| lia| lia]. }
  split; [| exact AOK]. intros x s IN. destruct (EL x s IN) as [junk C]. exists junk.
  eapply rheap_pres_rw_cells; [exact HP| exact C|]. cbn [cells_size csize]. destruct (AD x s IN) as (_ & _ & S0 & _).
  eapply rclient_range_sub; [exact (ER x s IN)| lia| rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by lia; lia| lia].
Qed.

Lemma mb_es_snoc_inv' : forall es : list mbe, es = [] \/ exists P xl sl, es = P ++ [(xl, sl)].
Proof. intros es. destruct es as [|e es'] eqn:E; [left; reflexivity| right]. rewrite <- E. apply mb_es_snoc_inv. rewrite E. discriminate. Qed.

